const storedWorkflowLiveStep = `-- name: StoredWorkflowLiveStep :many
SELECT s.status,s.output,s.attempt FROM workflow_steps s
WHERE s.run_id=$1::uuid
AND (($2::text='' AND s.step_name=$3::text AND s.foreach_parent IS NULL AND s.foreach_index IS NULL)
 OR ($2::text<>'' AND s.foreach_parent=$2::text AND s.foreach_index=$4::integer))
LIMIT 2
`

type StoredWorkflowLiveStepParams struct {
	RunID     pgtype.UUID
	LoopName  string
	StepName  string
	ItemIndex pgtype.Int4
}

type StoredWorkflowLiveStepRow struct {
	Status  string
	Output  []byte
	Attempt int32
}

func (q *Queries) StoredWorkflowLiveStep(ctx context.Context, db DBTX, arg StoredWorkflowLiveStepParams) ([]StoredWorkflowLiveStepRow, error) {
	rows, err := db.Query(ctx, storedWorkflowLiveStep,
		arg.RunID,
		arg.LoopName,
		arg.StepName,
		arg.ItemIndex,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []StoredWorkflowLiveStepRow{}
	for rows.Next() {
		var i StoredWorkflowLiveStepRow
		if err := rows.Scan(&i.Status, &i.Output, &i.Attempt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

